(* [comment removed for export] *)
Definition obi_seg2_post (sp : word) (gp tp : word) (s0 s1 a0v : word) (s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 rav : word) (F : bvmap 5 word) (fc : bv 32)
    (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6,
    ms' = MS (mkR rav sp gp tp t0 t1 t2 s0 s1 a0v a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc rav) fc None m (seg_rom rsegs)
    /\ stk rsegs m lo (bv_unsigned sp).

Definition obi_seg2_stmt (retpc : Z) : Prop := forall (lo : Z) (j8 : list byte)
    (sp : word) gp tp (rax t0 t1 t2 s0 s1 a0v a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 w1 w2 rav : word)
    (F : bvmap 5 word) fc (m : mem),
  rw_cells rsegs m (bv_unsigned sp - 32) [CB 8 j8] ->
  rw_cells rsegs m (bv_unsigned sp - 24) [C8 w1; C8 w2] ->
  rw_cells rsegs m (bv_unsigned sp - 8) [C8 rav] ->
  stk rsegs m lo (bv_unsigned sp - 32) -> lo + 32 <= bv_unsigned sp -> hceil <= lo -> bv_unsigned rav mod 2 = 0 ->
  mem_inv rsegs m ->
  evt rsegs (obi_seg2_post sp gp tp s0 s1 a0v s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 rav F fc lo m)
    (MS (mkR rax (wz (bv_unsigned sp - 32)) gp tp t0 t1 t2 s0 s1 a0v a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 retpc) fc None m (seg_rom rsegs)).

Local Ltac seg2_tac sp lo m F8 F24 FRA :=
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR; hcb;
  pose proof (munch_refl [(lo, bv_unsigned sp)]%Z m) as MU; pose proof (wmono_refl rsegs m) as WM;
  unfold P_OBI_RET, P_OCB_RET, wz in *;
  replace (bv_unsigned sp - 32) with (bv_unsigned sp + -32) in * by lia;
  replace (bv_unsigned sp - 24) with (bv_unsigned sp + -24) in * by lia;
  replace (bv_unsigned sp - 8) with (bv_unsigned sp + -8) in * by lia;
  join_frame F8 F24 (bv_unsigned sp + -32); join_frame F8 FRA (bv_unsigned sp + -32);
  (* [comment removed for export] *)
  step;
  lazymatch goal with ST0 : stk _ _ lo _ |- _ => release_frame F8 ST0 (bv_unsigned sp) end;
  step; step;
  unfold obi_seg2_post; finish.

